messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Red vs Blue Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background: #000; }
        canvas { display: block; }
        #info {
            position: absolute;
            top: 20px;
            left: 50%;
            transform: translateX(-50%);
            color: white;
            font-family: sans-serif;
            font-size: 24px;
            font-weight: bold;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.8);
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div id="info">RACE START!</div>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const TRACK_LENGTH = 200;
        const LANE_WIDTH = 3;
        const CAR_SPEED_BASE = 0.8;
        const CAR_SPEED_MAX = 1.8;
        const RACE_DURATION = 1500; // Frames roughly

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky blue
        scene.fog = new THREE.Fog(0x87CEEB, 20, 150);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 300);
        camera.position.set(0, 5, 10);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(10, 20, 10);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        dirLight.shadow.camera.near = 0.5;
        dirLight.shadow.camera.far = 50;
        dirLight.shadow.camera.left = -20;
        dirLight.shadow.camera.right = 20;
        dirLight.shadow.camera.top = 20;
        dirLight.shadow.camera.bottom = -20;
        scene.add(dirLight);

        // --- Environment ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(100, 500);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x3a3a3a, roughness: 0.8 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.z = -TRACK_LENGTH / 2 + 50;
        ground.receiveShadow = true;
        scene.add(ground);

        // Track markings
        const lineGeo = new THREE.PlaneGeometry(0.5, 500);
        const lineMat = new THREE.MeshBasicMaterial({ color: 0xffffff });
        const line = new THREE.Mesh(lineGeo, lineMat);
        line.rotation.x = -Math.PI / 2;
        line.position.y = 0.01;
        line.position.z = -TRACK_LENGTH / 2 + 50;
        scene.add(line);

        // Finish Line
        const finishGeo = new THREE.PlaneGeometry(10, 10);
        const finishMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const finishLine = new THREE.Mesh(finishGeo, finishMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.02, -TRACK_LENGTH / 2);
        scene.add(finishLine);

        // Checkered pattern on finish line
        const canvas = document.createElement('canvas');
        canvas.width = 64;
        canvas.height = 64;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = 'white';
        ctx.fillRect(0, 0, 64, 64);
        ctx.fillStyle = 'black';
        ctx.fillRect(0, 0, 32, 32);
        ctx.fillRect(32, 32, 32, 32);
        const checkTex = new THREE.CanvasTexture(canvas);
        const checkMat = new THREE.MeshStandardMaterial({ map: checkTex });
        const checkPlane = new THREE.Mesh(new THREE.PlaneGeometry(10, 10), checkMat);
        checkPlane.rotation.x = -Math.PI / 2;
        checkPlane.position.set(0, 0.03, -TRACK_LENGTH / 2);
        scene.add(checkPlane);

        // --- Car Factory ---
        function createCar(color) {
            const carGroup = new THREE.Group();

            // Chassis
            const chassisGeo = new THREE.BoxGeometry(2, 0.5, 4);
            const chassisMat = new THREE.MeshStandardMaterial({ color: color, metalness: 0.6, roughness: 0.2 });
            const chassis = new THREE.Mesh(chassisGeo, chassisMat);
            chassis.position.y = 0.5;
            chassis.castShadow = true;
            carGroup.add(chassis);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(1.8, 0.4, 2);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333, metalness: 0.5, roughness: 0.1 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.set(0, 1, -0.5);
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.3, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

            const positions = [
                { x: -1, z: 1.2 },
                { x: 1, z: 1.2 },
                { x: -1, z: -1.2 },
                { x: 1, z: -1.2 }
            ];

            positions.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, 0.4, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            return carGroup;
        }

        const redCar = createCar(0xFF0000);
        const blueCar = createCar(0x0000FF);

        // Initial positions
        redCar.position.set(-2.5, 0, TRACK_LENGTH / 2 - 10);
        blueCar.position.set(2.5, 0, TRACK_LENGTH / 2 - 10);
        scene.add(redCar);
        scene.add(blueCar);

        // --- Animation Logic ---
        let frame = 0;
        const infoDiv = document.getElementById('info');

        function updateCars() {
            frame++;
            if (frame > RACE_DURATION) frame = 0;

            // Calculate progress (0 to 1)
            const progress = frame / RACE_DURATION;

            // Blue Car: Starts fast, maintains speed, slows slightly at end
            // Red Car: Starts slow, accelerates, overtakes, wins

            let bluePos, redPos;

            if (progress < 0.3) {
                // Early stage: Blue leads
                bluePos = progress * 1.2; // Faster
                redPos = progress * 0.8;  // Slower
            } else if (progress < 0.7) {
                // Middle stage: Red accelerates
                bluePos = 0.36 + (progress - 0.3) * 0.8; // Slower
                redPos = 0.24 + (progress - 0.3) * 1.2;  // Faster
            } else {
                // End stage: Red wins
                bluePos = 0.68 + (progress - 0.7) * 0.8; // Slower
                redPos = 0.72 + (progress - 0.7) * 1.2;  // Faster
            }

            // Clamp positions
            bluePos = Math.min(1, Math.max(0, bluePos));
            redPos = Math.min(1, Math.max(0, redPos));

            // Convert progress to Z position (start at +100, end at -100)
            const startZ = TRACK_LENGTH / 2 - 10;
            const endZ = -TRACK_LENGTH / 2;
            const totalDist = startZ - endZ;

            redCar.position.z = startZ - (redPos * totalDist);
            blueCar.position.z = startZ - (bluePos * totalDist);

            // Camera follows the leading car
            const leaderZ = Math.min(redCar.position.z, blueCar.position.z);
            const camTargetZ = leaderZ + 15; // Camera slightly behind leader
            const camTargetX = 0;
            const camTargetY = 5;

            // Smooth camera movement
            camera.position.z += (camTargetZ - camera.position.z) * 0.1;
            camera.position.x += (camTargetX - camera.position.x) * 0.1;
            camera.position.y += (camTargetY - camera.position.y) * 0.1;
            camera.lookAt(camTargetX, 1, camTargetZ - 20);

            // Update info text
            if (redPos >= 1) {
                infoDiv.textContent = "RED WINS!";
                infoDiv.style.color = "#FF0000";
            } else if (bluePos >= 1) {
                infoDiv.textContent = "BLUE WINS!";
                infoDiv.style.color = "#0000FF";
            } else {
                infoDiv.textContent = "RACE IN PROGRESS...";
                infoDiv.style.color = "white";
            }
        }

        // --- Render Loop ---
        function animate() {
            requestAnimationFrame(animate);
            updateCars();
            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
